-- V1_22_0: RAG评测集扩充（搁置项攻关-任务11）
-- 在V1_16_1的24条基础上补充76条，达到100条
-- 覆盖 order/refund/inventory/logistics/purchase/goods/member 七个领域

INSERT IGNORE INTO `agent_rag_evaluation` (`merchant_id`, `question`, `expected_answer`, `relevant_chunks`, `domain`, `difficulty`) VALUES
-- ===== 订单领域补充 (12条) =====
(1, '客户下单后未付款，订单多久会自动关闭？', '待付款订单通常15分钟后自动关闭，具体时间以平台规则为准；关闭后库存释放，客户如需购买需重新下单。', '["order_status_001","order_pay_001"]', 'order', 'easy'),
(1, '拼团订单怎么取消？', '拼团订单在拼团成功前不可主动取消，超时未成团系统自动取消并全额退款；拼团成功后按普通订单取消流程处理。', '["order_group_001"]', 'order', 'easy'),
(1, '订单备注怎么修改？', '在订单详情页点击修改备注，可添加或修改商家备注和客户备注；已发货订单的客户备注不可修改，商家备注可随时更新。', '["order_memo_001"]', 'order', 'easy'),
(1, '如何合并多个订单一起发货？', '在订单列表中勾选同一客户的多个待发货订单，点击合并发货，选择同一物流单号和地址，系统自动合并出库；注意合并后库存扣减按订单分别记录。', '["order_merge_001"]', 'order', 'medium'),
(1, '订单拆分发货怎么操作？', '当一个订单有多个商品且部分缺货时，可在订单详情页选择拆分发货，先发出有货商品，剩余商品到货后补发；拆分后每个子订单有独立物流单号。', '["order_split_001"]', 'order', 'medium'),
(1, '客户要求修改订单商品数量怎么办？', '未付款订单可让客户取消重下；已付款未发货订单可在后台修改商品数量（需库存充足），差价多退少补；已发货订单不可修改，需走售后流程。', '["order_modify_001"]', 'order', 'medium'),
(1, '订单锁定状态是什么意思？', '订单锁定（状态22）通常是因为风控系统检测到异常（如频繁退款、异地登录、大额订单），需人工审核后解锁；锁定期间不可发货，审核通过后自动恢复待发货状态。', '["order_lock_001"]', 'order', 'medium'),
(1, '如何查询订单的操作日志？', '在订单详情页查看操作记录，包含下单、付款、发货、修改备注、退款等所有操作，每条记录有操作人、时间和操作内容；审计日志保留至少6个月。', '["order_log_001"]', 'order', 'easy'),
(1, '客户说没收到货但物流显示签收了怎么办？', '先核实物流签收详情（签收人、签收地点、时间），联系快递员确认是否放驿站/快递柜/代收点；若确认丢失，启动物流理赔流程，同时给客户补发或退款。', '["order_sign_001","logistics_lost_001"]', 'order', 'hard'),
(1, '预售订单的发货规则是什么？', '预售订单需在商品详情页标注预计发货时间，客户付款后订单进入待发货状态，到约定时间后仓库安排发货；超期未发货客户可申请退款并要求赔付。', '["order_presale_001"]', 'order', 'medium'),
(1, '订单金额计算错误怎么处理？', '核实商品单价、数量、优惠、运费、税费等各项金额，若系统计算错误需提交工单由技术人员核查；已付款订单差价通过退款或补款处理，不可直接修改订单金额。', '["order_amount_001"]', 'order', 'hard'),
(1, '如何设置订单自动审核？', '在系统设置中配置自动审核规则，如金额低于阈值、信用良好客户、非高风险地区等条件满足时自动审核通过；高风险订单保留人工审核。', '["order_auto_audit_001"]', 'order', 'medium'),

-- ===== 售后领域补充 (12条) =====
(1, '七天无理由退货的条件是什么？', '商品完好不影响二次销售，自签收之日起7天内可申请无理由退货；定制商品、贴身衣物、食品、虚拟商品等不支持；退货运费由客户承担（质量问题除外）。', '["refund_7day_001"]', 'refund', 'easy'),
(1, '退款多久能到账？', '退款审核通过后，原路返回支付账户，微信/支付宝通常1-3个工作日到账，银行卡3-7个工作日；大额退款可能需要人工复核，到账时间稍长。', '["refund_time_001"]', 'refund', 'easy'),
(1, '客户退货后仓库说影响二次销售怎么办？', '仓库验货时发现商品损坏、缺件、污损等影响二次销售的情况，拍照留证，可拒绝退款或扣除折旧费；客服需与客户沟通，提供验货照片，协商解决方案。', '["refund_damage_001"]', 'refund', 'hard'),
(1, '换货流程是怎样的？', '客户申请换货→客服审核→客户寄回原商品→仓库验货→发出新商品→客户签收；换货产生的运费按责任方承担，质量问题商家承担，无理由换货客户承担。', '["refund_exchange_001"]', 'refund', 'easy'),
(1, '售后超时未处理会怎样？', '商家需在48小时内处理售后申请，超时未处理系统自动同意客户申请；客服应每日查看待处理售后列表，避免超时自动退款造成损失。', '["refund_timeout_001"]', 'refund', 'easy'),
(1, '客户申请退款但商品已使用过怎么办？', '已使用商品不支持七天无理由退货；若存在质量问题，需客户提供照片/视频证据，核实后可按保修政策处理或协商部分退款；无质量问题的已使用商品可拒绝退款。', '["refund_used_001"]', 'refund', 'medium'),
(1, '部分退款怎么操作？', '在售后详情页选择部分退款，输入退款金额和原因，审核通过后按指定金额退款，订单其余部分正常完成；部分退款后订单不可再次申请全额退款。', '["refund_partial_001"]', 'refund', 'medium'),
(1, '售后单可以关闭后重新申请吗？', '已关闭的售后单在有效期内（通常15天）可重新申请；超过有效期需联系客服人工处理；同一订单同一商品最多申请3次售后。', '["refund_reapply_001"]', 'refund', 'easy'),
(1, '客户投诉售后处理太慢怎么安抚？', '先道歉并说明当前处理进度和预计完成时间，提供订单/售后单号方便客户查询；紧急情况可加急处理，必要时给予优惠券补偿；全程保持沟通，避免客户升级投诉。', '["refund_complaint_001"]', 'refund', 'medium'),
(1, '运费险怎么理赔？', '订单带有运费险时，退货退款完成后运费险自动理赔，理赔金额以保单为准，通常3-5个工作日到账；客服可协助查询理赔进度，不可承诺具体金额。', '["refund_insurance_001"]', 'refund', 'medium'),
(1, '商品过了保修期还能维修吗？', '超过保修期的商品可提供付费维修服务，客服需告知维修费用和周期，客户同意后寄修；若无法维修可建议以旧换新或购买新品。', '["refund_warranty_001"]', 'refund', 'medium'),
(1, '恶意退款客户怎么处理？', '记录客户退款历史，频繁退款/退货客户标记为高风险，订单需人工审核；确认恶意退款（如退回空包、调包）可拒绝退款并提交平台申诉，保留所有证据。', '["refund_fraud_001"]', 'refund', 'hard'),

-- ===== 库存领域补充 (10条) =====
(1, '库存预警怎么设置？', '在商品库存设置中填写预警阈值，当可用库存低于阈值时系统自动预警，可配置短信/站内信通知；支持按SKU单独设置，也可按商品统一设置。', '["inventory_alert_001"]', 'inventory', 'easy'),
(1, '库存调拨怎么操作？', '创建调拨单，选择调出仓库和调入仓库，填写商品和数量，审核通过后调出仓库出库，调入仓库确认入库后库存更新；调拨在途库存不计入可用库存。', "['inventory_transfer_001']", 'inventory', 'medium'),
(1, '如何处理库存盘盈盘亏？', '盘点后生成盘点单，系统自动计算盘盈盘亏数量，审核通过后生成库存调整单更新库存；盘盈需记录来源，盘亏需分析原因（损耗、丢失、错发），金额较大需审批。', '["inventory_check_002"]', 'inventory', 'medium'),
(1, '在途库存是什么意思？', '在途库存指采购单已下单但尚未入库的商品数量，加上现有库存为总库存；客户下单时只扣减可用库存（现有-锁定），在途库存到货后自动转为可用库存。', '["inventory_intransit_001"]', 'inventory', 'easy'),
(1, '库存锁定和库存占用有什么区别？', '库存锁定是客户下单未付款时临时锁定，超时未付款自动释放；库存占用是已付款订单占用，发货后扣减；两者都从可用库存中扣除，但锁定可释放，占用不可释放。', '["inventory_lock_001"]', 'inventory', 'medium'),
(1, '多仓库库存怎么管理？', '每个仓库独立管理库存，下单时按优先级或就近原则分配仓库；支持仓库间调拨，库存报表可按仓库汇总或合并查看；虚拟商品无需仓库管理。', '["inventory_warehouse_001"]', 'inventory', 'medium'),
(1, '库存为0但采购在途，客户能下单吗？', '取决于系统配置：若允许超卖（预售模式），客户可下单，发货时间标注为预售；若不允许超卖，库存为0时系统拦截下单，提示缺货。建议设置安全库存避免超卖。', '["inventory_oversell_001"]', 'inventory', 'medium'),
(1, '怎么导出库存报表？', '在库存管理页选择时间范围和仓库，点击导出，系统生成Excel包含期初、入库、出库、期末库存及金额；大数据量导出建议选择异步导出，完成后下载。', '["inventory_report_001"]', 'inventory', 'easy'),
(1, '批次库存怎么管理？', '开启批次管理后，每次入库生成批次号，记录生产日期、有效期、供应商等信息；出库时按先进先出（FIFO）或指定批次发货；临期商品系统自动预警。', '["inventory_batch_001"]', 'inventory', 'hard'),
(1, '库存成本怎么计算？', '支持移动加权平均法和先进先出法，每次入库更新成本单价，出库时按当前成本计算销售成本；成本调整需通过成本调整单，不可直接修改。', '["inventory_cost_001"]', 'inventory', 'hard'),

-- ===== 物流领域补充 (10条) =====
(1, '物流单号填错了怎么办？', '在发货后24小时内可修改物流单号，超过24小时需联系平台客服修改；修改后系统自动通知客户新的物流信息，原单号物流追踪停止。', '["logistics_waybill_001"]', 'logistics', 'easy'),
(1, '如何批量发货？', '在订单列表勾选多个待发货订单，点击批量发货，可选择统一物流公司或导入物流单号Excel；批量发货前需确认库存充足和地址正确。', '["logistics_batch_001"]', 'logistics', 'easy'),
(1, '电子面单打印失败怎么办？', '检查打印机连接和驱动、面单余额、网络连接；重新打印时系统提示是否已生成单号，已生成单号不可重复生成，可选择重新打印或换单。', '["logistics_print_002"]', 'logistics', 'medium'),
(1, '物流异常有哪些类型？', '常见物流异常包括：揽收超时、运输超时、派送异常、签收异常、包裹丢失、破损；系统自动标记异常订单，客服需跟进处理，必要时启动理赔。', '["logistics_exception_002"]', 'logistics', 'easy'),
(1, '怎么设置默认物流公司？', '在物流设置中选择默认物流公司和模板，发货时自动填充；可按商品类别或地区设置不同物流策略，偏远地区指定特定快递。', '["logistics_default_001"]', 'logistics', 'easy'),
(1, '运费模板怎么配置？', '按地区、重量、件数设置运费规则，支持首重+续重、满额包邮、指定地区不发货等；多个运费模板可按商品分配，下单时自动计算运费。', '["logistics_freight_001"]', 'logistics', 'medium'),
(1, '国际物流怎么处理？', '国际订单需选择跨境物流商，填写报关信息（商品名称、价值、数量），系统生成国际面单；关税和清关费用由客户承担，发货前需告知预计时效。', '["logistics_intl_001"]', 'logistics', 'hard'),
(2, '大件商品物流怎么安排？', '大件商品（家具、家电）需选择专线物流或零担物流，预约送货上门和安装时间；运费按体积/重量计算，需在商品页明确标注运费和配送范围。', '["logistics_bulky_001"]', 'logistics', 'medium'),
(1, '物流轨迹不更新超过多久算异常？', '揽收后24小时无轨迹更新、运输途中48小时无更新、派送中24小时未签收，系统标记为物流异常；客服需联系物流公司核实，超过72小时可启动理赔。', '["logistics_track_002"]', 'logistics', 'medium'),
(1, '如何处理客户拒收？', '客户拒收后包裹原路退回，仓库签收后核实商品完好；拒收原因需记录，非质量问题拒收运费由客户承担，质量问题拒收商家承担并退款。', '["logistics_reject_001"]', 'logistics', 'medium'),

-- ===== 采购/供应商领域补充 (12条) =====
(1, '采购单怎么创建？', '在采购管理中点击新建采购单，选择供应商和商品，填写采购数量和单价，系统自动计算金额；审核通过后发送给供应商，到货后入库。', '["purchase_create_001"]', 'purchase', 'easy'),
(1, '采购入库流程是什么？', '供应商送货→仓库验收（数量、质量）→填写实收数量→合格商品入库→不合格商品拒收或换货→采购单状态更新为已完成；入库后库存和应付账款自动更新。', '["purchase_inbound_001"]', 'purchase', 'easy'),
(1, '供应商管理包含哪些信息？', '供应商档案包含基本信息、联系方式、银行账户、供货商品清单、价格协议、账期、评级；支持供应商分类和标签，可按供货能力和质量评分排序。', '["purchase_supplier_001"]', 'purchase', 'easy'),
(1, '采购退货怎么操作？', '创建采购退货单，选择原采购单和退货商品，填写退货数量和原因，审核通过后通知供应商取货，仓库出库后扣减库存，应付账款相应减少。', '["purchase_return_001"]', 'purchase', 'medium'),
(1, '怎么根据库存自动生成采购建议？', '系统根据安全库存、在途库存、日均销量计算建议采购量，在采购建议页展示需补货商品；可一键生成采购单，也可手动调整数量后生成。', '["purchase_suggest_001"]', 'purchase', 'medium'),
(1, '采购价格变动怎么处理？', '供应商调价后需更新价格协议，新采购单按新价格执行；已审核未入库的采购单可修改价格（需审批），已入库的采购单价格不可修改。', '["purchase_price_001"]', 'purchase', 'medium'),
(1, '采购账期怎么管理？', '按供应商设置账期（如月结30天、货到付款），系统自动生成应付账款和到期提醒；付款后核销应付账款，支持部分付款和预付款抵扣。', '["purchase_payment_001"]', 'purchase', 'medium'),
(1, '供应商评级怎么算？', '综合供货及时率、产品合格率、价格竞争力、服务响应速度等指标，按月/季度自动计算评级；评级影响采购分配和账期，低评级供应商限制新增采购单。', '["purchase_rating_001"]', 'purchase', 'hard'),
(1, '采购订单可以部分入库吗？', '可以，采购单支持分批入库，每次入库填写实收数量，系统更新已入库数量和待入库数量；全部入库后采购单自动完成，部分入库可随时继续。', '["purchase_partial_001"]', 'purchase', 'easy'),
(1, '紧急采购怎么走加急流程？', '紧急采购单标记加急，跳过部分审批环节直接下单，但需事后补审批；加急采购价格可能高于常规采购，需在采购单备注原因和审批人。', '["purchase_urgent_001"]', 'purchase', 'medium'),
(1, '供应商对账怎么操作？', '按月生成对账单，包含该供应商所有采购入库、退货、付款明细，发送给供应商确认；确认无误后生成应付账款，差异部分需逐笔核对。', '["purchase_reconcile_001"]', 'purchase', 'medium'),
(1, '采购样品怎么管理？', '样品采购单独标记，入库时计入样品库存（不计入可售库存）；样品领用需登记，定期盘点样品库存；样品费用计入采购成本或营销费用。', '["purchase_sample_001"]', 'purchase', 'medium'),

-- ===== 商品领域补充 (10条) =====
(1, '怎么新增商品？', '在商品管理中点击新增，填写商品名称、分类、品牌、规格、价格、库存等信息，上传主图和详情图，保存后上架；新增商品需审核通过后前台可见。', '["goods_create_001"]', 'goods', 'easy'),
(1, 'SKU和SPU有什么区别？', 'SPU是标准产品单元（如iPhone 15），SKU是库存单位（如iPhone 15 128G 黑色）；一个SPU下可有多个SKU，每个SKU有独立价格和库存，下单时扣减SKU库存。', '["goods_sku_001"]', 'goods', 'easy'),
(1, '商品价格怎么批量修改？', '在商品列表勾选多个商品，点击批量改价，可按百分比或固定金额调整，修改后立即生效；批量改价需谨慎，建议先导出备份。', '["goods_price_001"]', 'goods', 'easy'),
(1, '商品上下架怎么操作？', '在商品列表选择商品，点击上架/下架，下架后前台不可见但后台保留；支持定时上下架，设置时间后系统自动执行；下架商品库存保留。', '["goods_shelf_001"]', 'goods', 'easy'),
(1, '商品分类怎么管理？', '支持多级分类（最多4级），可新增、编辑、排序分类，商品可归属多个分类；分类影响前台导航和筛选，删除分类前需先迁移商品。', '["goods_category_001"]', 'goods', 'easy'),
(1, '商品库存怎么同步到多个平台？', '开启多平台库存同步后，ERP库存为唯一库存源，销售平台库存按比例或固定数量同步；订单回传后自动扣减，避免超卖。', '["goods_sync_001"]', 'goods', 'medium'),
(1, '商品详情页图片有什么要求？', '主图建议800x800像素以上，白底无水印，最多9张；详情图宽度750px，高度不限，单张不超过3MB；图片需符合平台规范，违规图片会被下架。', '["goods_image_001"]', 'goods', 'easy'),
(1, '怎么设置商品促销价？', '在商品营销设置中创建促销活动，设置促销价、活动时间、限购数量；活动期间前台显示促销价和原价对比，活动结束自动恢复原价。', '["goods_promo_001"]', 'goods', 'medium'),
(1, '商品条码怎么管理？', '每个SKU可设置唯一条码（EAN/UPC/自定义），入库出库扫码识别；支持批量导入条码，无条码商品可生成内部码；条码重复时系统提示。', '["goods_barcode_001"]', 'goods', 'medium'),
(1, '滞销商品怎么处理？', '系统按销量和库存周转标记滞销商品（如90天无销量），可采取降价促销、捆绑销售、退货供应商、报废等措施；定期清理滞销品释放库存和资金。', '["goods_slow_001"]', 'goods', 'medium'),

-- ===== 会员/客户领域补充 (10条) =====
(1, '会员等级怎么划分？', '按累计消费金额或积分划分等级，如普通会员、银卡、金卡、钻石；不同等级享受不同折扣、积分倍率、专属客服；等级可自动升降或手动调整。', '["member_level_001"]', 'member', 'easy'),
(1, '积分怎么获取和使用？', '消费按金额比例获取积分（1元=1积分），签到、评价、分享也可获积分；积分可抵扣现金（100积分=1元）或兑换优惠券/礼品；积分有效期通常1年。', '["member_points_001"]', 'member', 'easy'),
(1, '客户标签怎么用？', '给客户打标签（如高价值、易退款、新客户、VIP），用于精准营销和客服优先级；支持手动打标签和自动规则打标签（如消费满X元自动标记VIP）。', '["member_tag_001"]', 'member', 'medium'),
(1, '怎么给会员发优惠券？', '在营销中心创建优惠券，选择定向发放给指定会员等级或标签客户，设置面额、门槛、有效期；发放后会员可在账户中查看和使用。', '["member_coupon_001"]', 'member', 'easy'),
(1, '客户信息怎么修改？', '客户可在前台修改基本信息（姓名、电话、地址），敏感信息（实名认证、银行卡）需验证后修改；客服可在后台协助修改，但需核实客户身份。', '["member_info_001"]', 'member', 'easy'),
(1, '会员储值怎么管理？', '会员可充值储值余额，消费时优先扣减；储值有充值赠送活动（如充100送10），余额不可提现，退款时优先退余额再退支付账户。', '["member_balance_001"]', 'member', 'medium'),
(1, '怎么查看客户购买历史？', '在客户详情页查看所有订单记录，包括订单金额、商品、状态、售后；可按时间筛选和导出，用于分析客户偏好和消费能力。', '["member_history_001"]', 'member', 'easy'),
(1, '客户投诉怎么处理和跟进？', '创建投诉工单，记录投诉内容、涉及订单、客户诉求，分配给客服处理；处理过程全程记录，处理完成后客户确认，工单关闭；超时未处理自动升级。', '["member_complaint_001"]', 'member', 'medium'),
(1, '沉睡客户怎么唤醒？', '系统标记90天未消费客户为沉睡客户，可定向发送优惠券、新品推荐、专属活动；唤醒成功率较低，建议配合短信和APP推送，成本较高时可放弃。', '["member_sleep_001"]', 'member', 'medium'),
(1, '客户黑名单怎么设置？', '确认恶意客户（频繁退款、欺诈、辱骂客服）后加入黑名单，黑名单客户无法下单和联系客服；需保留证据，误加可移除，黑名单操作需主管审批。', '["member_blacklist_001"]', 'member', 'hard');
